INSERT INTO public.ejercicios SELECT * FROM json_populate_record(NULL::public.ejercicios, '{"id":"15892e3e-1567-433d-ad74-dc6cf9adc272","nombre":"Abdominales Acostado con Disco","url_video":"y-BkLY8jyuw","comentario":"Configuración:\nAcostado en una colchoneta, con las piernas al ancho de caderas.\nTomar un disco con los brazos estirados entre ambas manos.\n\nEjecución:\nElevar el torso hacia adelante, manteniendo la espalda erguida. \nVolver al punto de inicio de manera controlada, apoyando la espalda baja primero.","creado_por":null,"created_at":"2026-10-30T03:35:26.22144+00:00","updated_at":"2026-11-20T11:37:08.650561+00:00","musculos_principales":["Core"],"musculos_secundarios":[]}') ON CONFLICT DO NOTHING;
INSERT INTO public.ejercicios SELECT * FROM json_populate_record(NULL::public.ejercicios, '{"id":"2c43bdae-c530-4ae7-a126-ee1e927f7a14","nombre":"Abducción de cadera Acostado con Tobillera","url_video":"n43TRof0MwU","comentario":"Configuración:\nAcostado, de manera lateral. \nFlexionar la pierna de base a 90º y mantener la pierna contraria estirada.\nColocar una tobillera en cada pierna. \n\nEjecuccion: \nRealizar una abducción lateral, manteniendo la pierna estirada. \nVolver al punto de inicio, contactando el pie con el suelo.","creado_por":null,"created_at":"2026-10-30T03:35:26.22144+00:00","updated_at":"2026-11-20T11:37:08.650561+00:00","musculos_principales":["Piernas"],"musculos_secundarios":[]}') ON CONFLICT DO NOTHING;
