INSERT INTO public.ejercicios SELECT * FROM json_populate_record(NULL::public.ejercicios, '{"id":"db7e7fc2-7599-4133-a380-293324b5fd94","nombre":"APERTURA EN MAQUINA","url_video":"kUTbYC_8Zg4","comentario":"-Mantene el codo levemente flexionado durante todo el recorrido","creado_por":null,"created_at":"2026-10-30T03:35:26.22144+00:00","updated_at":"2026-11-20T11:37:08.650561+00:00","musculos_principales":["Pecho"],"musculos_secundarios":[]}') ON CONFLICT DO NOTHING;
INSERT INTO public.ejercicios SELECT * FROM json_populate_record(NULL::public.ejercicios, '{"id":"01ca81d4-8e81-4595-ac5a-59669b51c446","nombre":"Aperturas Planas con Mancuernas","url_video":"z8juzhSsFKU","comentario":"Configuracion:\n- Acostado boca arriba en un banco plano.\n- Apoyo de Gluteo, escapula y pies sobre el suelo.\n- Agarrando dos mancuernas, una en cada mano por encima del pecho con los codos estirados.\n- Las palmas enfrentadas.\n\nEjecucion:\n- Separar lo brazos, moviendolos en centidos opuestos.\n- Durante el recorrido semi-flexionar el codo.\n- Abrir los brazos esta alinearse con el tronco.\n- Volver a la posicion inicial, juntando los brazos y extendiendo el codo al final.","creado_por":null,"created_at":"2026-10-30T03:35:26.22144+00:00","updated_at":"2026-11-20T11:37:08.650561+00:00","musculos_principales":["Pecho"],"musculos_secundarios":[]}') ON CONFLICT DO NOTHING;
INSERT INTO public.ejercicios SELECT * FROM json_populate_record(NULL::public.ejercicios, '{"id":"7eeb358c-e230-4a46-abf2-a6526fc6dd2f","nombre":"Camilla de Isquios","url_video":"SiwJ_T62l9c","comentario":"Configuración: \n- Acostado sobre la camilla de isquiotibiales.\n- Talones ubicados por debajo del rodillo. \n\nEjecución: \n- Realizar una flexión de rodilla, luego volver al punto de inicio.","creado_por":null,"created_at":"2026-10-30T03:35:26.22144+00:00","updated_at":"2026-11-20T11:37:08.650561+00:00","musculos_principales":["Piernas"],"musculos_secundarios":[]}') ON CONFLICT DO NOTHING;
INSERT INTO public.ejercicios SELECT * FROM json_populate_record(NULL::public.ejercicios, '{"id":"0c9d22aa-370c-41a4-a781-2b79c714cd62","nombre":"Caminata Lateral en Sentadilla","url_video":"g78CxAtjkCE","comentario":"Configuración:\nPiernas flexionadas a 90º, al ancho de caderas.\nBrazos al costado del cuerpo o juntos. \n\nEjecución:\nRealizar pasos laterales ampliando el ancho de caderas, manteniendo la posición de sentadilla. \nVolver al punto de inicio.","creado_por":null,"created_at":"2026-10-30T03:35:26.22144+00:00","updated_at":"2026-11-20T11:37:08.650561+00:00","musculos_principales":["Piernas"],"musculos_secundarios":[]}') ON CONFLICT DO NOTHING;
