INSERT INTO public.ejercicios SELECT * FROM json_populate_record(NULL::public.ejercicios, '{"id":"65200d67-f176-45a0-aaca-f067d5257196","nombre":"Curl 45°","url_video":"aTYlqC_JacQ","comentario":"Recostarse en un banco inclinado a 45° y dejar los brazos colgando a los costados para luego subir ambos hacia los hombros","creado_por":null,"created_at":"2026-10-30T03:35:26.22144+00:00","updated_at":"2026-11-20T11:37:08.650561+00:00","musculos_principales":["Brazos"],"musculos_secundarios":[]}') ON CONFLICT DO NOTHING;
INSERT INTO public.ejercicios SELECT * FROM json_populate_record(NULL::public.ejercicios, '{"id":"c7521ded-a63c-48fc-a019-f01872eb3f5c","nombre":"Curl Concentrado","url_video":"GnSwYWNgWuk","comentario":"Configuracion:\n-Sentarse en un banco y ubicar el brazo extendido sobre el aductor sosteniendo la mancuerna.\nEjecucion:\n-Flexionar el codo elevando la mancuerna hacia la cadera y descender de manera controlada.","creado_por":null,"created_at":"2026-10-30T03:35:26.22144+00:00","updated_at":"2026-11-20T11:37:08.650561+00:00","musculos_principales":["Brazos"],"musculos_secundarios":[]}') ON CONFLICT DO NOTHING;
