INSERT INTO public.ejercicios SELECT * FROM json_populate_record(NULL::public.ejercicios, '{"id":"c6a5debf-dc7b-4d33-a607-05658a33008b","nombre":"Despliegue c/ rueda abdominal","url_video":"DA2QGI0NPWU","comentario":"Configuración:\nBoca abajo, con el apoyo de ambas rodillas flexionadas.\nComenzar con las manos estiradas sosteniendo la rueda abdominal.\nLa espalda lumbar se encuentra redondeada. \nEjecución:\nRolar la rueda hacia adelante, de modo que nuestra espalda pueda seguir manteniendo la misma curva, hasta contactar el pecho con el suelo.\nVolver a la posición de inicio.","creado_por":null,"created_at":"2026-10-30T03:35:26.22144+00:00","updated_at":"2026-11-20T11:37:08.650561+00:00","musculos_principales":["Core"],"musculos_secundarios":[]}') ON CONFLICT DO NOTHING;
INSERT INTO public.ejercicios SELECT * FROM json_populate_record(NULL::public.ejercicios, '{"id":"fbc74266-fca5-41a3-a7fd-75d6482e73d6","nombre":"Dominada al Pecho Supina","url_video":"kwdx1Kk-RDc","comentario":"Configuración:\nColgarse de la barra, con los brazos completamen estirados, sin apoyar los pies sobre el suelo.\nUbicar los brazos ligeramente al ancho superior de hombros y utilizando un agarre supino.\nEjecución:\nRealizar con potencia un tirón de brazos, el pecho debe tocar la barra.\nLos pies deben mantenerse al ancho de caderas, sin abrirse en exceso.\nVolver al punto de inicio.","creado_por":null,"created_at":"2026-10-30T03:35:26.22144+00:00","updated_at":"2026-11-20T11:37:08.650561+00:00","musculos_principales":["Espalda"],"musculos_secundarios":[]}') ON CONFLICT DO NOTHING;
INSERT INTO public.ejercicios SELECT * FROM json_populate_record(NULL::public.ejercicios, '{"id":"608a25d1-0532-4acb-a633-5cc6ef1b0ae0","nombre":"Dominada isométrica","url_video":"bjGe73KUJWo","comentario":null,"creado_por":null,"created_at":"2026-10-30T03:35:26.22144+00:00","updated_at":"2026-11-20T11:37:08.650561+00:00","musculos_principales":["Espalda"],"musculos_secundarios":[]}') ON CONFLICT DO NOTHING;
INSERT INTO public.ejercicios SELECT * FROM json_populate_record(NULL::public.ejercicios, '{"id":"cd9e0518-3ee7-4b79-a592-125796eaf724","nombre":"Dorsiflexion y movilidad de cadera","url_video":"mBppBW8mob8","comentario":"Ejercicio para la movilidad del tobillo y la cadera","creado_por":null,"created_at":"2026-10-30T03:35:26.22144+00:00","updated_at":"2026-11-20T11:37:08.650561+00:00","musculos_principales":["Piernas"],"musculos_secundarios":[]}') ON CONFLICT DO NOTHING;
INSERT INTO public.ejercicios SELECT * FROM json_populate_record(NULL::public.ejercicios, '{"id":"476bfb69-21ef-4681-af65-ee8bf9f3990a","nombre":"Estocadas Frontales con Barra","url_video":"nqTPrgqSuTI","comentario":"Configuración:\n-Colocar la barra por encima de los hombros.\n-Mantener un agarre frontal. \n\nEjecución:\n-Caminar hacia adelante, a traves de estocadas. \n-Mantener el torso sobre las caderas en todo momento.","creado_por":null,"created_at":"2026-10-30T03:35:26.22144+00:00","updated_at":"2026-11-20T11:37:08.650561+00:00","musculos_principales":["Piernas"],"musculos_secundarios":[]}') ON CONFLICT DO NOTHING;
INSERT INTO public.ejercicios SELECT * FROM json_populate_record(NULL::public.ejercicios, '{"id":"582fc07a-e7e0-4366-aa3b-93ff2f6b3a6e","nombre":"Estocadas Isometricas","url_video":"869fS-uDgz0","comentario":"Configuración:\n- De pie, al ancho de caderas.\n\nEjecución:\n- Realizar un paso hacia adelante y flexionar una rodilla a 90 grados.\n-Pierna de atrás en la misma posición. \n- Mantener la cantidad de segundos estipulados. \n-Alternar de pierna.","creado_por":null,"created_at":"2026-10-30T03:35:26.22144+00:00","updated_at":"2026-11-20T11:37:08.650561+00:00","musculos_principales":["Piernas"],"musculos_secundarios":[]}') ON CONFLICT DO NOTHING;
INSERT INTO public.ejercicios SELECT * FROM json_populate_record(NULL::public.ejercicios, '{"id":"f5190986-2dcc-40b4-a22a-2bd1fda33de9","nombre":"Extension de rodilla","url_video":"Jd9rYOetS9U","comentario":"Activacion de cadena posterior","creado_por":null,"created_at":"2026-10-30T03:35:26.22144+00:00","updated_at":"2026-11-20T11:37:08.650561+00:00","musculos_principales":["Piernas"],"musculos_secundarios":[]}') ON CONFLICT DO NOTHING;
INSERT INTO public.ejercicios SELECT * FROM json_populate_record(NULL::public.ejercicios, '{"id":"72c7a0d9-3341-4b2a-a987-3de8a62a09a2","nombre":"Extension de triceps barra V","url_video":"v7f6PjSAO-4","comentario":"Ejercicio para aislar los triceps","creado_por":null,"created_at":"2026-10-30T03:35:26.22144+00:00","updated_at":"2026-11-20T11:37:08.650561+00:00","musculos_principales":["Brazos"],"musculos_secundarios":[]}') ON CONFLICT DO NOTHING;
INSERT INTO public.ejercicios SELECT * FROM json_populate_record(NULL::public.ejercicios, '{"id":"0de62cb9-7f0d-406b-ac00-c6a1ef6f966c","nombre":"Extension de Triceps Supino a un Brazo en Polea","url_video":"8EmiPnxZS4M","comentario":"Configuración:\n- De pie, al frente de una polea. Ubicar el agarre en la parte superior.\n- Utilizar un agarre unilateral con toma supina y flexionar el codo a 90º.\n\nEjecucción:\n-Realizar una extensión unilateral,  llevando la mano a la altura de la cadera.\n- Evitar despegar el codo cerca del cuerpo o balancearse.\n- Volver al punto de inicio.\n- Realizar las repeticiones estipuladas y cambiar de brazo.","creado_por":null,"created_at":"2026-10-30T03:35:26.22144+00:00","updated_at":"2026-11-20T11:37:08.650561+00:00","musculos_principales":["Brazos"],"musculos_secundarios":[]}') ON CONFLICT DO NOTHING;
INSERT INTO public.ejercicios SELECT * FROM json_populate_record(NULL::public.ejercicios, '{"id":"de50165c-084b-44d6-a57c-21b2d6d1f7ed","nombre":"Extensiones de Espalda a 45°","url_video":"wmB_AETn1fs","comentario":"Configuración:\nColocar los pies en la base de un GHD y mantener la columna erguida pero levemente inclinada hacia adelante. \nUbicar los brazos por encima del pecho y piernas estiradas. \nEjecución:\nIniciar el movimiento arqueando la espalda y mirando ligeramente hacia abajo.\nVolver al punto de inicio.","creado_por":null,"created_at":"2026-10-30T03:35:26.22144+00:00","updated_at":"2026-11-20T11:37:08.650561+00:00","musculos_principales":["Espalda"],"musculos_secundarios":[]}') ON CONFLICT DO NOTHING;
INSERT INTO public.ejercicios SELECT * FROM json_populate_record(NULL::public.ejercicios, '{"id":"c530e026-700b-4a56-ab65-f41c588337e2","nombre":"Facepull parado con soga","url_video":"0Po47vvj9g4","comentario":"Configuración:\n- De pie, frente a la polea.\n- Utilizar la soga agarrándola en pronación con los nudillos enfrentados.\nEjecución:\n-Traccionar con los codos hacia atrás.\n-Realizar un ajuste escapular.\n-Volver a a la posición incial.","creado_por":null,"created_at":"2026-10-30T03:35:26.22144+00:00","updated_at":"2026-11-20T11:37:08.650561+00:00","musculos_principales":["Hombros"],"musculos_secundarios":[]}') ON CONFLICT DO NOTHING;
INSERT INTO public.ejercicios SELECT * FROM json_populate_record(NULL::public.ejercicios, '{"id":"d6b0e0d9-5d7e-46f6-a369-c10370bcfd82","nombre":"Flexiones de brazos","url_video":"JhFCg91vXR0","comentario":"Configuración:\n-Ubicar el cuerpo boca abajo con la rodillas apoyadas en el suelo y las piernas juntas. \n-Ubicar los brazos estirados a la altura de los hombros, cerca del cuerpo.\n\nInstrucciones:\n-Flexionar los codos en un angulo de 45º, con la intención de llevar el pecho al suelo.\n-Completar el rango total de movimiento, o llegar a los 90º, \n-Extender los codos. \n-Mantener una línea recta a lo largo de toda la trayectoria de movimiento.","creado_por":null,"created_at":"2026-10-30T03:35:26.22144+00:00","updated_at":"2026-11-07T23:55:56.091123+00:00","musculos_principales":["Pecho"],"musculos_secundarios":["Hombro anterior","Triceps"]}') ON CONFLICT DO NOTHING;
INSERT INTO public.ejercicios SELECT * FROM json_populate_record(NULL::public.ejercicios, '{"id":"2fd2a01d-70cd-4313-acc4-c96adbd71038","nombre":"Flexiones de Brazos Cerradas","url_video":"Lz1aFtuNvEQ","comentario":"Configuración:\n-Ubicar el cuerpo boca abajo con las piernas juntas y estiradas. \n-Ubicar los brazos estirados por dentro de la anchura de los hombros.\n\nInstrucciones:\n-Flexionar los codos  en un angulo de 45º, con la intención de llevar el pecho a al suelo. \n-Mantener una línea recta a lo largo de toda la trayectoria de movimiento.","creado_por":null,"created_at":"2026-10-30T03:35:26.22144+00:00","updated_at":"2026-11-20T11:37:08.650561+00:00","musculos_principales":["Pecho"],"musculos_secundarios":[]}') ON CONFLICT DO NOTHING;
INSERT INTO public.ejercicios SELECT * FROM json_populate_record(NULL::public.ejercicios, '{"id":"fc5cbe0e-68a0-441f-ad3f-6e422a33c560","nombre":"Flexiones de Brazos con Discos","url_video":"KadL9HpmWSg","comentario":"Configuración:\n-Ubicar el cuerpo boca abajo con las piernas juntas y estiradas. \n-Ubicar los brazos estirados a la altura de los hombros, sobre un superficie elevada. Mientras mayor inclinación, menor dificultad de ejecucción. \n\nInstrucciones:\n-Flexionar los codos en un angulo de 45º, con la intención de llevar el pecho a la superficie seleccionada. \n-Una vez completado el rango de moviemiento, extender los codos. \n-Mantener una línea recta a lo largo de toda la trayectoria de movimiento.","creado_por":null,"created_at":"2026-10-30T03:35:26.22144+00:00","updated_at":"2026-11-20T11:37:08.650561+00:00","musculos_principales":["Pecho"],"musculos_secundarios":[]}') ON CONFLICT DO NOTHING;
INSERT INTO public.ejercicios SELECT * FROM json_populate_record(NULL::public.ejercicios, '{"id":"0a2c2da5-3f3d-4e25-a800-e1fcce32a646","nombre":"Fondos con pausa","url_video":"WBQqSX1vy3A","comentario":"Ejercicio para los pectorales y triceps","creado_por":null,"created_at":"2026-10-30T03:35:26.22144+00:00","updated_at":"2026-11-20T11:37:08.650561+00:00","musculos_principales":["Pecho"],"musculos_secundarios":[]}') ON CONFLICT DO NOTHING;
INSERT INTO public.ejercicios SELECT * FROM json_populate_record(NULL::public.ejercicios, '{"id":"e26cd601-0e6f-4f44-a3a2-07a236f54cad","nombre":"Fondos estrictos con carga","url_video":"QGcbSt4NSC0","comentario":"Configuración:\n-Comenzar con los brazos estirados sobre la barra.\n-Sostener el peso entre las piernas o en un cinturón.\n\nEjecución:\n-Iniciar el movimiento empujando los codos hacia atrás.\n-Ubicar los hombros debajo de los codos en la parte inferior.\n-Descender la cadera por debajo de la barra.","creado_por":null,"created_at":"2026-10-30T03:35:26.22144+00:00","updated_at":"2026-11-20T11:37:08.650561+00:00","musculos_principales":["Pecho"],"musculos_secundarios":[]}') ON CONFLICT DO NOTHING;
INSERT INTO public.ejercicios SELECT * FROM json_populate_record(NULL::public.ejercicios, '{"id":"ed40902f-15c4-4b48-a6ca-8de025514c76","nombre":"Fondos Paralelas Asistido con Maquina","url_video":"zQ9ELqwBgAE","comentario":"Configuración:\nUbicar ambos pies sobre la plataforma, manteniendo las piernas estiradas.\nTomar cada manija con agarre neutro.\n\nEjecución:\nDescender de manera controlada, llevando los codos hacia atrás e inclinando el torso levemente hacia adelante.\nVolver al punto de inicio.","creado_por":null,"created_at":"2026-10-30T03:35:26.22144+00:00","updated_at":"2026-11-20T11:37:08.650561+00:00","musculos_principales":["Pecho"],"musculos_secundarios":[]}') ON CONFLICT DO NOTHING;
INSERT INTO public.ejercicios SELECT * FROM json_populate_record(NULL::public.ejercicios, '{"id":"3beb9f1d-351f-4437-a83a-3d67637848fe","nombre":"Hip thrust en maquina","url_video":"Xk8ZEl4i_O8","comentario":"Ejercicio de hipertrofia para la cadena posterior","creado_por":null,"created_at":"2026-10-30T03:35:26.22144+00:00","updated_at":"2026-11-20T11:37:08.650561+00:00","musculos_principales":["Piernas"],"musculos_secundarios":[]}') ON CONFLICT DO NOTHING;
INSERT INTO public.ejercicios SELECT * FROM json_populate_record(NULL::public.ejercicios, '{"id":"9fc0dd17-e9dd-48f1-ab5b-72b903476441","nombre":"Jalón al pecho agarre neutro","url_video":null,"comentario":null,"creado_por":null,"created_at":"2026-10-30T03:35:51.982968+00:00","updated_at":"2026-11-07T23:55:56.091123+00:00","musculos_principales":["Dorsal ancho"],"musculos_secundarios":[]}') ON CONFLICT DO NOTHING;
INSERT INTO public.ejercicios SELECT * FROM json_populate_record(NULL::public.ejercicios, '{"id":"ad020a89-eea0-43ff-abea-bc1fcc47c7fa","nombre":"Mariposa para Hombros Posteriores","url_video":"VpTc5ACO0Qc","comentario":"Configuración:\n-Regular el asiento de la máquina de modo que los pies esten en contacto con el suelo.\n-Sentarse con el torso apoyado en el respaldo y tomar las manijas de los costados de modo que los codos queden levemente flexionados, utilizando un agarre neutro. \nEjecución:\n- Realizar aperturas laterales de ambos brazos de manera simultánea, de modo que las manos se alineen con los hombros.\n-Volver al punto de inicio.","creado_por":null,"created_at":"2026-10-30T03:35:26.22144+00:00","updated_at":"2026-11-20T11:37:08.650561+00:00","musculos_principales":["Hombros"],"musculos_secundarios":[]}') ON CONFLICT DO NOTHING;
INSERT INTO public.ejercicios SELECT * FROM json_populate_record(NULL::public.ejercicios, '{"id":"bcbac147-2a78-4063-a6af-f2386f2f06b3","nombre":"Movilidad de tobillo en sentadilla","url_video":"weC9PRj6n3U","comentario":"Ejercicio de movilidad para el tren inferior","creado_por":null,"created_at":"2026-10-30T03:35:26.22144+00:00","updated_at":"2026-11-20T11:37:08.650561+00:00","musculos_principales":["Piernas"],"musculos_secundarios":[]}') ON CONFLICT DO NOTHING;
INSERT INTO public.ejercicios SELECT * FROM json_populate_record(NULL::public.ejercicios, '{"id":"a36b7410-ba07-4def-ab5d-3069f5b2b2ff","nombre":"Patada de gluteo diagonal","url_video":"1p1nU8CB98k","comentario":"Ejercicio para aislar el gluteo medio","creado_por":null,"created_at":"2026-10-30T03:35:26.22144+00:00","updated_at":"2026-11-20T11:37:08.650561+00:00","musculos_principales":["Piernas"],"musculos_secundarios":[]}') ON CONFLICT DO NOTHING;
INSERT INTO public.ejercicios SELECT * FROM json_populate_record(NULL::public.ejercicios, '{"id":"d514bf7c-c4c5-4a26-a153-b20cd4ca017f","nombre":"Patada de gluteo lateral en polea","url_video":"vSqhrbzZb7A","comentario":"Configuración: \n- De pie, posicionado de costado a la polea.\n- Tobillera puesta en la pierna que va a ejecutar el movimiento.\n- Pierna de apoyo por delante de la que va a realizar el movimiento.\n- Brazos teniendo un apoyo sobre soporte de la polea\n\nEjecución: \n- Realizar una patada lateral hacia el costado contrario a la polea.\n- Volver al punto de inicio.","creado_por":null,"created_at":"2026-10-30T03:35:26.22144+00:00","updated_at":"2026-11-20T11:37:08.650561+00:00","musculos_principales":["Piernas"],"musculos_secundarios":[]}') ON CONFLICT DO NOTHING;
INSERT INTO public.ejercicios SELECT * FROM json_populate_record(NULL::public.ejercicios, '{"id":"7d4702d4-35ae-47b8-a737-c6c00b78d5de","nombre":"Peso Muerto Rumano a una Pierna con Manc.","url_video":"PHZ-RBb8KYc","comentario":"Configuración:\n-Mantener las mancuernas cerca del cuerpo.\n-Comenzar con el apoyo de un solo pie, con las mancuernas en ambas manos.\n\nEjecución:\n-Realizar una flexión de cadera, y por ende, ir flexionando la rodilla de base levemente. \n-La pierna contraria se mantiene recta, acompañando el movimiento de la cadera.\n-Bajar las mancuernas pegadas al cuerpo.\n-Mantener la columna neutra. \n-Regresar extendiendo la cadera.\n-Completar las repeticiones estipuladas y cambiar de pierna.","creado_por":null,"created_at":"2026-10-30T03:35:26.22144+00:00","updated_at":"2026-11-20T11:37:08.650561+00:00","musculos_principales":["Piernas"],"musculos_secundarios":[]}') ON CONFLICT DO NOTHING;
INSERT INTO public.ejercicios SELECT * FROM json_populate_record(NULL::public.ejercicios, '{"id":"208d5c64-957b-4fcf-ab4c-08c22ac26453","nombre":"Plancha 4 apoyos","url_video":"tdQL8yQ6fQE","comentario":null,"creado_por":null,"created_at":"2026-10-30T03:35:26.22144+00:00","updated_at":"2026-11-20T11:37:08.650561+00:00","musculos_principales":["Core"],"musculos_secundarios":["Lumbares"]}') ON CONFLICT DO NOTHING;
INSERT INTO public.ejercicios SELECT * FROM json_populate_record(NULL::public.ejercicios, '{"id":"7b6143fa-6c2a-45f5-a9be-abd7954160a4","nombre":"Plancha baja + plancha alta","url_video":"2sYoLRFTkxQ","comentario":"Ejercicio de activación","creado_por":null,"created_at":"2026-10-30T03:35:26.22144+00:00","updated_at":"2026-11-20T11:37:08.650561+00:00","musculos_principales":["Core"],"musculos_secundarios":[]}') ON CONFLICT DO NOTHING;
INSERT INTO public.ejercicios SELECT * FROM json_populate_record(NULL::public.ejercicios, '{"id":"90076515-125a-4b30-a030-98748a900baa","nombre":"Plancha Frontal desplazando Elemento","url_video":"aFrXv1bdioY","comentario":"Configuración:\n-Ubicar el cuerpo boca abajo con los brazos estirados.\n-Colocar una sola mancuerna de peso ligero/moderado a su lado.\n\nEjecución:\n-Alinear hombros, caderas,  rodillas y talones  en línea recta.\n-Comenzar con una mancuerna en el lado derecho del cuerpo.\n-Con la mano izquierda, agarrar la mancuerna.\n-Colocar la mancuerna del lado izquierdo y volver a la posición de plancha.\n-Ahora realizar el mismo movimiento en el lado opuesto.","creado_por":null,"created_at":"2026-10-30T03:35:26.22144+00:00","updated_at":"2026-11-20T11:37:08.650561+00:00","musculos_principales":["Core"],"musculos_secundarios":[]}') ON CONFLICT DO NOTHING;
INSERT INTO public.ejercicios SELECT * FROM json_populate_record(NULL::public.ejercicios, '{"id":"3652ccf8-63a6-4b5c-a242-638b3f187011","nombre":"Plancha lateral c/ rotación","url_video":"RXlHKL_NEN8","comentario":"Configuración: \nApoyar un antebrazo en contacto con el suelo y mantener ambas piernas estiradas, una por encima de la otra.\nEjecución:\nEl brazo que ese encuentra estirado en línea con el hombro, llevarlo por debajo del cuerpo.\nVolver al punto de inicio.","creado_por":null,"created_at":"2026-10-30T03:35:26.22144+00:00","updated_at":"2026-11-20T11:37:08.650561+00:00","musculos_principales":["Core"],"musculos_secundarios":[]}') ON CONFLICT DO NOTHING;
INSERT INTO public.ejercicios SELECT * FROM json_populate_record(NULL::public.ejercicios, '{"id":"3473c3f2-f239-4d69-a62a-d8abb92ff936","nombre":"Plancha Toco Hombro","url_video":"D5bBXAew8Es","comentario":"Configuración:\n-Ubicar el cuerpo boca abajo en el suelo con los brazos extendidos.\n-Piernas al ancho de cadera.\n-Manos alineadas con hombros.\n\nEjecucción:\n-Mantener la posición de plancha.\n-Quitar un brazo y tocar el hombro contrario al de ejecucción.\n-Volver a colocar el apoyo.\n-Repetir con el brazo contrario el mismo movimiento.","creado_por":null,"created_at":"2026-10-30T03:35:26.22144+00:00","updated_at":"2026-11-20T11:37:08.650561+00:00","musculos_principales":["Core"],"musculos_secundarios":[]}') ON CONFLICT DO NOTHING;
INSERT INTO public.ejercicios SELECT * FROM json_populate_record(NULL::public.ejercicios, '{"id":"21311af0-704c-41ff-a074-16a956fda259","nombre":"Prensa 45°","url_video":"yZmx_Ac3880","comentario":"Configuración:\n-Sentado en la máquina, con la cabeza, la espalda, las caderas, y las nalgas presionando por igual contra sus respectivos apoyos almohadillados.\n-Si el ángulo del respaldo es ajustable, moverlo\nhacia arriba o hacia abajo para que el tronco y las piernas formen un ángulo de 90 grados aproximadamente , con los pies colocados\ncorrectamente sobre su plataforma de apoyo y las rodillas completamente extendidas. \n-Los pies han de estar separados a la anchura entre la cadera y los hombros,\nplanos sobre la plataforma de apoyo y sus puntas dirigidas ligeramente hacia fuera. \n\nEjecucion:\n-Agarrar los manillares, y extender  las rodillas para elevar la plataforma.\n-Quitar el mecanismo de sujeción de la plataforma de los pies.\n-Comenzar flexionando las caderas y las rodillas lenta y controladamente.\n-Mantener las caderas y las nalgas presionando contra el asiento y la espalda.\n\nContinuar el movimiento de descenso hasta que se produzca una de estas\ncuatro situaciones:\nl. Los muslos quedan paralelos con la plataforma de los pies (si se puede\nconseguir).\n2. Las nalgas pierden contacto con el asiento.\n3. Las caderas se separan del almohadillado de la espalda.\n4. Los talones se separan de la plataforma de los pies.\n\n-Empujar hacia arriba y controladamente de los pies extendiendo las caderas y las rodillas. \n-Continuar empujando hacia arriba hasta que las rodillas estén estiradas por completo, pero sin bloquearlas forzadamente.","creado_por":null,"created_at":"2026-10-30T03:35:26.22144+00:00","updated_at":"2026-11-20T11:37:08.650561+00:00","musculos_principales":["Piernas"],"musculos_secundarios":[]}') ON CONFLICT DO NOTHING;
INSERT INTO public.ejercicios SELECT * FROM json_populate_record(NULL::public.ejercicios, '{"id":"6dee16eb-63e0-4a2b-a10d-32f4f6e6e080","nombre":"Press Frances con Barra EZ en Banco Plano","url_video":"l3rHYPtMUo8","comentario":"Configuración:\n-Ubicarse acostado en un banco plano.\n-Piernas al ancho de caderas.\n-Brazos estirados por delante del hombro, sosteniendo una barra Z.\n\nEjecución:\n-Flexionar los codos llevándolos a la altura de la frente.\n-Volver a la posición inicial, extendiendo los brazos.","creado_por":null,"created_at":"2026-10-30T03:35:26.22144+00:00","updated_at":"2026-11-20T11:37:08.650561+00:00","musculos_principales":["Brazos"],"musculos_secundarios":[]}') ON CONFLICT DO NOTHING;
INSERT INTO public.ejercicios SELECT * FROM json_populate_record(NULL::public.ejercicios, '{"id":"1213e846-0ff9-4750-a129-31a242ef5356","nombre":"Press francés con mancuernas en banco plano","url_video":"Rn6LgSEPsDc","comentario":null,"creado_por":null,"created_at":"2026-10-30T03:35:26.22144+00:00","updated_at":"2026-11-20T11:37:08.650561+00:00","musculos_principales":["Brazos"],"musculos_secundarios":[]}') ON CONFLICT DO NOTHING;
INSERT INTO public.ejercicios SELECT * FROM json_populate_record(NULL::public.ejercicios, '{"id":"0bdd3b1c-26fe-4c7c-abf7-aa59c486ff43","nombre":"Press Inclinado con Mancuernas","url_video":"jMQA3XtJSgo","comentario":"Configuración:\nAcostarse boca arriba sobre banco plano.\nPuntos de apoyo en pies, glúteos y escapular.\nUsar una posición de pies amplia con las rodillas hacia afuera.\nAjustar los omóplatos contra el banco.\nComenzar con las mancuernas en línea con el torso y sobre el hombro.\n\nEjecución:\nBajar las mancuernas a la parte inferior de los pectorales.\nPermanecer con los pies en el suelo.\nAjustar los glúteos en contacto con el banco, durante todo el movimiento.\nSubir las mancuernas, hasta alinear las mueñcas con los hombros.","creado_por":null,"created_at":"2026-10-30T03:35:26.22144+00:00","updated_at":"2026-11-20T11:37:08.650561+00:00","musculos_principales":["Pecho"],"musculos_secundarios":[]}') ON CONFLICT DO NOTHING;
INSERT INTO public.ejercicios SELECT * FROM json_populate_record(NULL::public.ejercicios, '{"id":"14919757-ac5b-4b1b-a00c-13c0e2439178","nombre":"Press militar c/ banda","url_video":"5_hYNIjsSvs","comentario":null,"creado_por":null,"created_at":"2026-10-30T03:35:26.22144+00:00","updated_at":"2026-11-20T11:37:08.650561+00:00","musculos_principales":["Hombros"],"musculos_secundarios":[]}') ON CONFLICT DO NOTHING;
INSERT INTO public.ejercicios SELECT * FROM json_populate_record(NULL::public.ejercicios, '{"id":"e979e45c-166c-4d5e-ab2b-26db8f6b9430","nombre":"Press militar en guia","url_video":"ia4NTz2XIQA","comentario":"Colocar la guia a la altura de nuestras claviculas. Con un banco con espaldar recto, colocarnos bajo la guia y empujar hacia arriba. Descender hasta que la guía vuelva a la posición inicial para finalizar la repetición.","creado_por":null,"created_at":"2026-10-30T03:35:26.22144+00:00","updated_at":"2026-11-20T11:37:08.650561+00:00","musculos_principales":["Hombros"],"musculos_secundarios":["Hombro anterior"]}') ON CONFLICT DO NOTHING;
INSERT INTO public.ejercicios SELECT * FROM json_populate_record(NULL::public.ejercicios, '{"id":"357e1785-c4af-4271-a03c-d561ffd51c3e","nombre":"Press militar parado con barra","url_video":"BjmI3A5_hWs","comentario":"Con la barra colocada sobre nuestro pecho superior, tomar aire y apretar el abdomen. Empujar en linea vertical, evitando que la barra vaya hacia delante. Una vez la barra este arriba, debemos descenderla nuevamente hasta la posición inicial.","creado_por":null,"created_at":"2026-10-30T03:35:26.22144+00:00","updated_at":"2026-11-20T11:37:08.650561+00:00","musculos_principales":["Hombros"],"musculos_secundarios":["Hombro anterior"]}') ON CONFLICT DO NOTHING;
INSERT INTO public.ejercicios SELECT * FROM json_populate_record(NULL::public.ejercicios, '{"id":"f2b732c6-623d-4def-ac84-9f6fe940d3a8","nombre":"Press Plano con Barra","url_video":"EsTu2NVM1EI","comentario":"Configuración:\n- Acostarse boca arriba sobre banco plano.\n- Puntos de apoyo en pies, glúteos y escapular.\n- Agarrar barra mayor al ancho de hombros.\n\nEjecución:\n- Realizar una retracción escapular .\n- Sacar barra del soporte.\n- Tomar aire y bajar barra direccionada al pecho.\n- Codos a 45 grados en movimiento de bajada y subida.\n- Levantar la barra hacia el punto de inicio.","creado_por":null,"created_at":"2026-10-30T03:35:26.22144+00:00","updated_at":"2026-11-20T11:37:08.650561+00:00","musculos_principales":["Pecho"],"musculos_secundarios":[]}') ON CONFLICT DO NOTHING;
INSERT INTO public.ejercicios SELECT * FROM json_populate_record(NULL::public.ejercicios, '{"id":"b8e0e509-955b-402e-abd8-ae16eade90a5","nombre":"Press Plano con Barra + Pausa (1\",2\",3\")","url_video":"NudCjXj1R2M","comentario":"Configuración:\n- Acostarse sobre banco plano\n- puntos de apoyo en pies, glúteos y escapulas.\n- Agarrar la barra al ancho de hombros.\nEjecución:\n- Realizar una retracción escapular.\n- Sacar la barra del soporte y bajarla direcciona hacia el pecho.\n- Aguantar 1,2,3 segundo en el pecho. \n- Volver al punto de inicio.","creado_por":null,"created_at":"2026-10-30T03:35:26.22144+00:00","updated_at":"2026-11-20T11:37:08.650561+00:00","musculos_principales":["Pecho"],"musculos_secundarios":[]}') ON CONFLICT DO NOTHING;
INSERT INTO public.ejercicios SELECT * FROM json_populate_record(NULL::public.ejercicios, '{"id":"7277039e-6d8d-4d6f-afcd-ed44b3020fca","nombre":"Press plano con mancuernas","url_video":"qW519gsE2M8","comentario":null,"creado_por":null,"created_at":"2026-10-30T03:35:26.22144+00:00","updated_at":"2026-11-20T11:37:08.650561+00:00","musculos_principales":["Pecho"],"musculos_secundarios":[]}') ON CONFLICT DO NOTHING;
INSERT INTO public.ejercicios SELECT * FROM json_populate_record(NULL::public.ejercicios, '{"id":"54661849-67ec-48f1-a90e-c37522f0e7af","nombre":"Puente de Gluteo Asimetrico","url_video":"9-r_r2KlpI8","comentario":"Configuración:\n-Acostarse en el suelo, mirando hacia arriba. \n-Una rodilla flexionada y la otra semi-estirada, con los pies apoyados en el piso.\n-Mantener el contacto con los hombros en el suelo en todo momento.\n\nEjecución:\n-Elevar la cadera, de modo que las rodillas y caderas se encuentren en una misma línea horizontal.\n-Aguantar arriba durante 1'''' y contraer los glúteos.\n-Evitar la hiperextensión de la columna.\n-Al volver a la posición inicial, bajar la cadera de manera controlada.","creado_por":null,"created_at":"2026-10-30T03:35:26.22144+00:00","updated_at":"2026-11-20T11:37:08.650561+00:00","musculos_principales":["Piernas"],"musculos_secundarios":[]}') ON CONFLICT DO NOTHING;
INSERT INTO public.ejercicios SELECT * FROM json_populate_record(NULL::public.ejercicios, '{"id":"84d87480-deea-4d89-ad9e-b2d0230154ea","nombre":"Pullover en polea alta","url_video":"5cqIDziQ5Ko","comentario":"Ejercicio para los dorsales","creado_por":null,"created_at":"2026-10-30T03:35:26.22144+00:00","updated_at":"2026-11-20T11:37:08.650561+00:00","musculos_principales":["Espalda"],"musculos_secundarios":[]}') ON CONFLICT DO NOTHING;
INSERT INTO public.ejercicios SELECT * FROM json_populate_record(NULL::public.ejercicios, '{"id":"f0ec50f8-cd75-4d67-a66c-7b371f043aee","nombre":"Remo al mentón c/ pesa rusa","url_video":"6iybrrctpjs","comentario":null,"creado_por":null,"created_at":"2026-10-30T03:35:26.22144+00:00","updated_at":"2026-11-20T11:37:08.650561+00:00","musculos_principales":["Espalda"],"musculos_secundarios":[]}') ON CONFLICT DO NOTHING;
INSERT INTO public.ejercicios SELECT * FROM json_populate_record(NULL::public.ejercicios, '{"id":"bfb24d47-2238-46ed-a6d7-84d0688e4d91","nombre":"Remo al Mentón+ Press de Hombro c/ Banda","url_video":"YE70G9abE98","comentario":"Configuración: \nDe pie, al ancho de caderas.\nUbicar una banda circular de tensión baja, en el soporte inferior de una columna.\nColocar las manos al ancho de hombros.\nEjecución:\nRealizar una tracción llevando ambos codos hacia atrás y luego realizando un press por encima de la cabeza. \nVolver al punto de inicio.","creado_por":null,"created_at":"2026-10-30T03:35:26.22144+00:00","updated_at":"2026-11-20T11:37:08.650561+00:00","musculos_principales":["Hombros"],"musculos_secundarios":[]}') ON CONFLICT DO NOTHING;
INSERT INTO public.ejercicios SELECT * FROM json_populate_record(NULL::public.ejercicios, '{"id":"f339d55c-0dfd-4f32-a75b-b069f2bb5975","nombre":"Remo con barra desde rack","url_video":"GXqSFyntKPo","comentario":"Ejercicio de fuerza máxima para los musculos de tracción","creado_por":null,"created_at":"2026-10-30T03:35:26.22144+00:00","updated_at":"2026-11-20T11:37:08.650561+00:00","musculos_principales":["Espalda"],"musculos_secundarios":[]}') ON CONFLICT DO NOTHING;
INSERT INTO public.ejercicios SELECT * FROM json_populate_record(NULL::public.ejercicios, '{"id":"b182cdf4-c36a-4a93-a855-b1bb1e93d1de","nombre":"Remo gorila","url_video":"eIM8d32x2Go","comentario":"Ejercicio de fuerza para los musculos de la espalda","creado_por":null,"created_at":"2026-10-30T03:35:26.22144+00:00","updated_at":"2026-11-20T11:37:08.650561+00:00","musculos_principales":["Espalda"],"musculos_secundarios":[]}') ON CONFLICT DO NOTHING;
INSERT INTO public.ejercicios SELECT * FROM json_populate_record(NULL::public.ejercicios, '{"id":"a0da644a-198d-4b0f-a286-56efcd318e13","nombre":"Remo Inclinado Agarre Prono con Barra","url_video":"GIqICKwpUHw","comentario":"Configuracion:\n-Los pies a la ancho de los hombros, hacer peso muerto con la barra para iniciar el ejercicio.\n-Mantenga ambas manos en un agarre prono (las palmas hacia el cuerpo) con las manos mayor al ancho de los hombros.\n-Mantener la espalda baja plana.\n\nEjecución:\n-Bisagra en la cadera, desplazando las caderas hacia atrás.\n-Continuar hasta que el pecho quede en frente al suelo o paralelo.\n-Tirar de los codos hacia atrás y juntos hasta que la barra llegue a la parte superior de los abdominales o boca del estomago.\n-Volver a la posición inicial.","creado_por":null,"created_at":"2026-10-30T03:35:26.22144+00:00","updated_at":"2026-11-20T11:37:08.650561+00:00","musculos_principales":["Espalda"],"musculos_secundarios":[]}') ON CONFLICT DO NOTHING;
INSERT INTO public.ejercicios SELECT * FROM json_populate_record(NULL::public.ejercicios, '{"id":"3b1647e1-5771-4b74-aaf3-5c72df77affd","nombre":"Remo unilateral con Giro de Torso","url_video":"OJqzswBViq0","comentario":"Ejecución:\nUtilizar un banco plano para apoyar un brazo y una pierna del mismo lado.\nPierna contraria estirada, y brazo estirado con una mancuerna.\n\nConfiguración:\nLlevar un brazo hacia atrás a la altura del pectoral.\nRotar levemente el torso.\nVolver a la posición inicial.","creado_por":null,"created_at":"2026-10-30T03:35:26.22144+00:00","updated_at":"2026-11-20T11:37:08.650561+00:00","musculos_principales":["Espalda"],"musculos_secundarios":[]}') ON CONFLICT DO NOTHING;
INSERT INTO public.ejercicios SELECT * FROM json_populate_record(NULL::public.ejercicios, '{"id":"64817423-63ce-45a1-a411-44d827c273b5","nombre":"Rotaciones de hombro con disco","url_video":"ygvnl_u_nnA","comentario":"Ejercicio de resistencia para los hombros","creado_por":null,"created_at":"2026-10-30T03:35:26.22144+00:00","updated_at":"2026-11-20T11:37:08.650561+00:00","musculos_principales":["Hombros"],"musculos_secundarios":[]}') ON CONFLICT DO NOTHING;
INSERT INTO public.ejercicios SELECT * FROM json_populate_record(NULL::public.ejercicios, '{"id":"0342ef22-9092-4b15-adbf-6da9f445e82c","nombre":"Rotaciones Dorsales","url_video":"ds3umIYJDrE","comentario":"Configuración: \nEn posición de cuadrupedia, manos estiradas al ancho de hombros en contacto con el suelo.\nCabeza en línea con la columna.\nEjecución:\nRealizar una rotación interna, de modo que un brazo estirado se ubique por debajo del hombro contario.\nEl mismo brazo debe contactar con la colchenta.\nLuego realizar una rotación externa. \nVolver al punto de inicio.","creado_por":null,"created_at":"2026-10-30T03:35:26.22144+00:00","updated_at":"2026-11-20T11:37:08.650561+00:00","musculos_principales":["Espalda"],"musculos_secundarios":[]}') ON CONFLICT DO NOTHING;
INSERT INTO public.ejercicios SELECT * FROM json_populate_record(NULL::public.ejercicios, '{"id":"ed06151d-8e3c-405f-ae17-1e955e962439","nombre":"Rotaciones torácicas arrodillado","url_video":"pvWRd-JinBs","comentario":null,"creado_por":null,"created_at":"2026-10-30T03:35:26.22144+00:00","updated_at":"2026-11-20T11:37:08.650561+00:00","musculos_principales":["Espalda"],"musculos_secundarios":[]}') ON CONFLICT DO NOTHING;
INSERT INTO public.ejercicios SELECT * FROM json_populate_record(NULL::public.ejercicios, '{"id":"7a38528b-9b84-4025-afe5-89570f647c73","nombre":"Rotaciones toracicas en Cuadripedia","url_video":"s-lZ6VfElPo","comentario":"Configuración:\n-Colocar las manos, pies y rodillas en contacto con el suelo\n-Comenzar con los brazos extendidos.\n-Ubicar las rodillas alineadas con la cadera y los pies alineados con las rodillas.\n-No muever las caderas durante el movimiento. \n\nEjecución:\n-Colocar una mano contra la oreja.\n-Deje caer ese codo debajo del tronco, apuntando al espacio debajo de la axila opuesta.\n-Regresar a la posición inicial y continuar levantando el codo lo más alto posible.\n-No mover las caderas durante todo el movimiento.","creado_por":null,"created_at":"2026-10-30T03:35:26.22144+00:00","updated_at":"2026-11-20T11:37:08.650561+00:00","musculos_principales":["Espalda"],"musculos_secundarios":[]}') ON CONFLICT DO NOTHING;
INSERT INTO public.ejercicios SELECT * FROM json_populate_record(NULL::public.ejercicios, '{"id":"050c8756-5f7f-4cc9-a323-3aeae589c753","nombre":"Russian Twist c/ Mancuerna","url_video":"Tau0hsW8iR0","comentario":null,"creado_por":null,"created_at":"2026-10-30T03:35:26.22144+00:00","updated_at":"2026-11-20T11:37:08.650561+00:00","musculos_principales":["Core"],"musculos_secundarios":[]}') ON CONFLICT DO NOTHING;
INSERT INTO public.ejercicios SELECT * FROM json_populate_record(NULL::public.ejercicios, '{"id":"77d7856b-6957-4ac3-a46c-fbfdacdd51b9","nombre":"Sentadilla + bisagra","url_video":"TMjo01fOESs","comentario":"Ejercicio de movilidad para tren inferior","creado_por":null,"created_at":"2026-10-30T03:35:26.22144+00:00","updated_at":"2026-11-20T11:37:08.650561+00:00","musculos_principales":["Piernas"],"musculos_secundarios":[]}') ON CONFLICT DO NOTHING;
INSERT INTO public.ejercicios SELECT * FROM json_populate_record(NULL::public.ejercicios, '{"id":"16ca8589-d145-475a-a3f6-b37e7cbb71fd","nombre":"Sentadilla Aerea","url_video":"hOzIP_sDfU0","comentario":"Configuración:\n-Pies al ancho de caderas.\n-Puntas de los pies levemente hacia afuera.\n-Brazos estirados hacia el frente.\n\nEjecución:\n-Bajar hasta llegar a la posición de cuclillas.\n-Volver a la posición inicial de manera controlada.","creado_por":null,"created_at":"2026-10-30T03:35:26.22144+00:00","updated_at":"2026-11-20T11:37:08.650561+00:00","musculos_principales":["Piernas"],"musculos_secundarios":[]}') ON CONFLICT DO NOTHING;
INSERT INTO public.ejercicios SELECT * FROM json_populate_record(NULL::public.ejercicios, '{"id":"b62de09b-26a9-4fe7-a1ef-30a61f725d58","nombre":"Sentadilla bulgara 45° con mancuernas","url_video":"MGh5po3i5cE","comentario":"Configuración:\n-Sostener una mancuerna en cada mano.\n-Los brazos permanecen rectos a los lados.\n-Una pierna da un paso largo hacia adelante al ancho de la cadera.\n-El pie trasero va encima del soporte.\n\nEjecución:\n-Descender hasta que la rodilla trasera toque el suelo o el pliegue de la cadera quede por debajo de la rodilla.\n-Mantener el talón en contacto con el suelo durante todo el movimiento.\n-Volver a subir hasta extender completamente la cadera.","creado_por":null,"created_at":"2026-10-30T03:35:26.22144+00:00","updated_at":"2026-11-20T11:37:08.650561+00:00","musculos_principales":["Piernas"],"musculos_secundarios":["Glúteos"]}') ON CONFLICT DO NOTHING;
INSERT INTO public.ejercicios SELECT * FROM json_populate_record(NULL::public.ejercicios, '{"id":"730a60f0-49ac-4384-acf7-9d4e2f4443c9","nombre":"Sentadilla bulgara 90° con barra","url_video":"IJkhxApUqP4","comentario":"Configuración:\n-Ubicar una barra en un rack o jaula.\n-Colocar la barra en la parte superior de los trapecios.\n-Brazos por fuera de los hombros.\n-Realizar un ajuste escapular. \n-Una pierna da un paso largo hacia adelante al ancho de la cadera.\n-Pie trasero va encima de un soporte o banco plano. \n\nEjecución:\n-Descender hasta que la rodilla trasera toque el suelo.\n-Descender con el torso recto. \n-Mantener el talón en contacto con el suelo durante todo el movimiento.\n-Volver a subir hasta extender completamente la cadera.","creado_por":null,"created_at":"2026-10-30T03:35:26.22144+00:00","updated_at":"2026-11-20T11:37:08.650561+00:00","musculos_principales":["Piernas"],"musculos_secundarios":["Glúteos"]}') ON CONFLICT DO NOTHING;
INSERT INTO public.ejercicios SELECT * FROM json_populate_record(NULL::public.ejercicios, '{"id":"8f58bf34-3e36-40d6-af71-8a72b35f2d70","nombre":"Sentadilla Bulgara con Peso Corporal","url_video":"kBQ1krvKFBU","comentario":"Configuración:\n-Los brazos permanecen rectos a los lados.\n-Una pierna da un paso largo hacia adelante al ancho de la cadera.\n-El pie trasero va encima del soporte.\n\nEjecución:\n-Descender hasta que la rodilla trasera toque el suelo o el pliegue de la cadera quede por debajo de la rodilla.\n-Mantener el talón en contacto con el suelo durante todo el movimiento.\n-Volver a subir hasta extender completamente la cadera.","creado_por":null,"created_at":"2026-10-30T03:35:26.22144+00:00","updated_at":"2026-11-20T11:37:08.650561+00:00","musculos_principales":["Piernas"],"musculos_secundarios":[]}') ON CONFLICT DO NOTHING;
INSERT INTO public.ejercicios SELECT * FROM json_populate_record(NULL::public.ejercicios, '{"id":"c5d56949-3a06-4168-a087-9ea2e8bceafb","nombre":"Sentadilla con Barra","url_video":"rrJIyZGlK8c","comentario":"Configuración:\n-Colocar la barra en un rack o jaula de potencia justo por debajo de los hombros.\n-Ubicar la barra en la parte superior de los omoplatos. \n-Sujetar con ambas manos a cada lado.\n-Pies al ancho de caderas.\n\nEjecución: \n-Alejarse del soporte del rack o jaula.\n-Colocar las piernas al ancho de caderas, con los dedos de los pies apuntando ligeramente hacia afuera.\n-Bajar la barra hasta llegar a la posición de cuclillas.\n-Volver a la posición inicial de manera controlada.","creado_por":null,"created_at":"2026-10-30T03:35:26.22144+00:00","updated_at":"2026-11-20T11:37:08.650561+00:00","musculos_principales":["Piernas"],"musculos_secundarios":[]}') ON CONFLICT DO NOTHING;
INSERT INTO public.ejercicios SELECT * FROM json_populate_record(NULL::public.ejercicios, '{"id":"58fb0ac9-c454-4217-a72b-67e3e942a2a1","nombre":"Sentadilla Copa (Enfocada en Cuádriceps)","url_video":"UZvdUM3kBSc","comentario":"Configuración:\n- Apoyar ambos talones sobre un disco.\n- De pie, piernas juntas.\n- Manos sosteniendo una pesa rusa. \n\nEjecución: \n- Realizar una flexión de rodillas, llevando la cadera hacia atrás.\n- Centrar el punto de apoyo en los talones de los pies.\n- Llegar a los 90º y volver al punto de inicio.","creado_por":null,"created_at":"2026-10-30T03:35:26.22144+00:00","updated_at":"2026-11-20T11:37:08.650561+00:00","musculos_principales":["Piernas"],"musculos_secundarios":[]}') ON CONFLICT DO NOTHING;
