INSERT INTO public.ejercicios SELECT * FROM json_populate_record(NULL::public.ejercicios, '{"id":"a68fe779-de36-4690-af14-366be05f62c7","nombre":"Sentadilla Frontal agarre cruzado","url_video":"Ceh8f8pIeKY","comentario":"Configuración:\n-Colocar la barra en un rack o jaula de potencia justo por debajo de los hombros.\n-Apoyar la barra en los hombros, con los brazos cruzados. \n-Codos altos.\n-Agarre desde la punta de los dedos.\n-De pie, al ancho de caderas.\n\nEjecución:\n-Alejarse del soporte del rack o jaula.\n-Colocar las piernas al ancho de las caderas, con los dedos de los pies apuntando ligeramente hacia afuera.\n-Bajar la barra hasta llegar a la posición de cuclillas.\n-Volver a la posición inicial de manera controlada.","creado_por":null,"created_at":"2026-10-30T03:35:26.22144+00:00","updated_at":"2026-11-20T11:37:08.650561+00:00","musculos_principales":["Piernas"],"musculos_secundarios":[]}') ON CONFLICT DO NOTHING;
