INSERT INTO public.ejercicios SELECT * FROM json_populate_record(NULL::public.ejercicios, '{"id":"a53f51bf-55b3-4629-a795-1dba2fb9986e","nombre":"Sillon de Cuadriceps","url_video":"MpEydcQ1oDw","comentario":"Configuración:\n- Sentarse sobre el sillón de cuádriceps.\n- Pies posicionados por debajo del rodillo con puntas direccionadas hacia arriba.\n\nEjecución: \n- Realizar una extensión de rodilla y luego regresar al punto de inicio.","creado_por":null,"created_at":"2026-10-30T03:35:26.22144+00:00","updated_at":"2026-11-20T11:37:08.650561+00:00","musculos_principales":["Piernas"],"musculos_secundarios":[]}') ON CONFLICT DO NOTHING;
