-- ============================================================================
-- GOZSter · Seed de producción (GOZS-705 / D-1)
-- ============================================================================
-- Datos de referencia reales para producción creada desde cero (camino A).
-- Sin personas: 0 auth.users, 0 perfiles, 0 alumnos, 0 emails, 0 teléfonos.
-- Idempotente: ejecutarlo varias veces sobre la misma base no duplica filas.
--
-- Contenido:
--   1. Catálogo de ejercicios (89 filas; 86 con video, 3 sin video; creado_por = NULL).
--   2. Plantillas de entrenamiento (3 plantillas activas, 7 días, 37 ejercicios en rutina).
--   3. Feriados nacionales de Argentina 2026 (19) y 2027 (16).
--   4. Planes de membresía: sección opcional comentada (pendiente de precios ARS).
--
-- Ejecución: correr después de aplicar todas las migraciones (`supabase db push`)
-- desde el SQL Editor de Supabase o psql con rol postgres / service_role.
-- ============================================================================

BEGIN;

-- ----------------------------------------------------------------------------
-- 1. CATÁLOGO DE EJERCICIOS (89 filas; creado_por = NULL)
-- ----------------------------------------------------------------------------

-- ----------------------------------------------------------------------------
-- 2. PLANTILLAS DE ENTRENAMIENTO (3 plantillas, 7 días, 37 ejercicios)
-- ----------------------------------------------------------------------------



-- ----------------------------------------------------------------------------
-- 3. FERIADOS NACIONALES DE ARGENTINA (2026 y 2027)
-- ----------------------------------------------------------------------------
-- GOZS-229: feriados nacionales de Argentina 2026. Idempotente (ON CONFLICT (fecha) DO NOTHING).
-- Fuente: https://www.argentina.gob.ar/interior/feriados-nacionales-2026
-- id determinista (md5 de la fecha): una base restaurada coincide fila por fila con el seed.
SELECT md5('feriado:' || v.fecha)::uuid, v.fecha::date, v.nombre, v.tipo FROM (VALUES
  ('2026-01-01', 'Año Nuevo', 'INAMOVIBLE'),
  ('2026-02-16', 'Carnaval', 'INAMOVIBLE'),
  ('2026-02-17', 'Carnaval', 'INAMOVIBLE'),
  ('2026-03-23', 'Día no laborable con fines turísticos', 'PUENTE'),
  ('2026-03-24', 'Día Nacional de la Memoria por la Verdad y la Justicia', 'INAMOVIBLE'),
  ('2026-04-02', 'Día del Veterano y de los Caídos en la Guerra de Malvinas', 'INAMOVIBLE'),
  ('2026-04-03', 'Viernes Santo', 'INAMOVIBLE'),
  ('2026-05-01', 'Día del Trabajador', 'INAMOVIBLE'),
  ('2026-05-25', 'Día de la Revolución de Mayo', 'INAMOVIBLE'),
  ('2026-06-15', 'Paso a la Inmortalidad del General Güemes (trasladado)', 'TRASLADABLE'),
  ('2026-06-20', 'Paso a la Inmortalidad del General Belgrano', 'INAMOVIBLE'),
  ('2026-07-09', 'Día de la Independencia', 'INAMOVIBLE'),
  ('2026-07-10', 'Día no laborable con fines turísticos', 'PUENTE'),
  ('2026-08-17', 'Paso a la Inmortalidad del General San Martín', 'TRASLADABLE'),
  ('2026-10-12', 'Día del Respeto a la Diversidad Cultural', 'TRASLADABLE'),
  ('2026-11-23', 'Día de la Soberanía Nacional (trasladado)', 'TRASLADABLE'),
  ('2026-12-07', 'Día no laborable con fines turísticos', 'PUENTE'),
  ('2026-12-08', 'Inmaculada Concepción de María', 'INAMOVIBLE'),
  ('2026-12-25', 'Navidad', 'INAMOVIBLE')
) AS v(fecha, nombre, tipo)
ON CONFLICT (fecha) DO NOTHING;

-- GOZS-705: feriados nacionales de Argentina 2027. Idempotente (ON CONFLICT (fecha) DO NOTHING).
-- Fechas calculadas con la Ley 27.399: Pascua 28/3 (Carnaval 8 y 9/2, Viernes Santo 26/3);
-- trasladables: mar/mié -> lunes anterior, jue/vie -> lunes siguiente, sáb/dom no se mueven.
-- Los días no laborables con fines turísticos (PUENTE) de 2027 no estaban publicados al
-- 22/11/2026: cargarlos con un INSERT aparte cuando salga el decreto.
-- id determinista (md5 de la fecha), igual que feriados_ar_2026.sql.
SELECT md5('feriado:' || v.fecha)::uuid, v.fecha::date, v.nombre, v.tipo,
       'https://www.argentina.gob.ar/interior/feriados-nacionales-2027'
FROM (VALUES
  ('2027-01-01', 'Año Nuevo', 'INAMOVIBLE'),
  ('2027-02-08', 'Carnaval', 'INAMOVIBLE'),
  ('2027-02-09', 'Carnaval', 'INAMOVIBLE'),
  ('2027-03-24', 'Día Nacional de la Memoria por la Verdad y la Justicia', 'INAMOVIBLE'),
  ('2027-03-26', 'Viernes Santo', 'INAMOVIBLE'),
  ('2027-04-02', 'Día del Veterano y de los Caídos en la Guerra de Malvinas', 'INAMOVIBLE'),
  ('2027-05-01', 'Día del Trabajador', 'INAMOVIBLE'),
  ('2027-05-25', 'Día de la Revolución de Mayo', 'INAMOVIBLE'),
  ('2027-06-20', 'Paso a la Inmortalidad del General Belgrano', 'INAMOVIBLE'),
  ('2027-06-21', 'Paso a la Inmortalidad del General Güemes (trasladado)', 'TRASLADABLE'),
  ('2027-07-09', 'Día de la Independencia', 'INAMOVIBLE'),
  ('2027-08-16', 'Paso a la Inmortalidad del General San Martín (trasladado)', 'TRASLADABLE'),
  ('2027-10-11', 'Día del Respeto a la Diversidad Cultural (trasladado)', 'TRASLADABLE'),
  ('2027-11-20', 'Día de la Soberanía Nacional', 'TRASLADABLE'),
  ('2027-12-08', 'Inmaculada Concepción de María', 'INAMOVIBLE'),
  ('2027-12-25', 'Navidad', 'INAMOVIBLE')
) AS v(fecha, nombre, tipo)
ON CONFLICT (fecha) DO NOTHING;

